27	import { hideAllTooltips } from '../TldrawUiTooltip'
28	import { useTldrawUiMenuContext } from './TldrawUiMenuContext'
29	
30	/** @public */
31	export interface TLUiMenuItemProps<
32		TranslationKey extends string = string,
33		IconType extends string = string,
34	> {
35		id: string
36		/**
37		 * The icon to display on the item. Icons are only shown in certain menu types.
38		 */
39		icon?: IconType | TLUiIconJsx
40		/**
41		 * An icon to display to the left of the menu item.
42		 */
43		iconLeft?: IconType | TLUiIconJsx
44		/**
45		 * The keyboard shortcut to display on the item.
46		 */
47		kbd?: string
48		/**
49		 * The label to display on the item. If it's a string, it will be translated. If it's an object, the keys will be used as the language keys and the values will be translated.
50		 */
51		label?: TranslationKey | { [key: string]: TranslationKey }
52		/**
53		 * If the editor is in readonly mode and the item is not marked as readonlyok, it will not be rendered.
54		 */
55		readonlyOk?: boolean
56		/**
57		 * The function to call when the item is clicked.
58		 */
59		onSelect(source: TLUiEventSource): Promise<void> | void
60		/**
61		 * Whether this item should be disabled.
62		 */
63		disabled?: boolean
64		/**
65		 * Prevent the menu from closing when the item is clicked
66		 */
67		noClose?: boolean
68		/**
69		 * Whether to show a spinner on the item.
70		 */
71		spinner?: boolean
72		/**
73		 * Whether the item is selected.
74		 */
75		isSelected?: boolean
76		/**
77		 * The function to call when the item is dragged. If this is provided, the item will be draggable.
78		 */
79		onDragStart?(source: TLUiEventSource, info: TLPointerEventInfo): void
80	}
81	
82	/** @public @react */
83	export function TldrawUiMenuItem<
84		TranslationKey extends string = string,
85		IconType extends string = string,
86	>({
87		disabled = false,
88		spinner = false,
89		readonlyOk = false,
90		id,
91		kbd,
92		label,
93		icon,
94		iconLeft,
95		onSelect,
96		noClose,
97		isSelected,
98		onDragStart,
99	}: TLUiMenuItemProps<TranslationKey, IconType>) {
100		const { type: menuType, sourceId } = useTldrawUiMenuContext()
101	
102		const msg = useTranslation()
103		const dir = useDirection()
104	
105		const [disableClicks, setDisableClicks] = useState(false)
106	
107		const isReadonlyMode = useReadonly()
108		if (isReadonlyMode && !readonlyOk) return null
109	
110		const labelToUse = unwrapLabel(label, menuType)
111		const kbdToUse = kbd ? kbdStr(kbd) : undefined
112	
113		const labelStr = labelToUse ? msg(labelToUse as TLUiTranslationKey) : undefined
114		const titleStr = labelStr && kbdToUse ? `${labelStr} ${kbdToUse}` : labelStr
115	
116		switch (menuType) {
117			case 'menu': {
118				return (
119					<TldrawUiDropdownMenuItem>
120						<TldrawUiButton
121							type="menu"
122							data-testid={`${sourceId}.${id}`}
123							disabled={disabled}
124							onClick={(e) => {
125								if (noClose) {
126									preventDefault(e)
127								}
128								if (disableClicks) {
129									setDisableClicks(false)
130								} else {
131									onSelect(sourceId)
132								}
133							}}
134						>
135							{iconLeft && <TldrawUiButtonIcon icon={iconLeft} small />}
136							<TldrawUiButtonLabel>{labelStr}</TldrawUiButtonLabel>
137							{kbd && <TldrawUiKbd>{kbd}</TldrawUiKbd>}
138						</TldrawUiButton>
139					</TldrawUiDropdownMenuItem>
140				)
141			}
142			case 'context-menu': {
143				// Hide disabled context menu items
144				if (disabled) return null
145	
146				return (
147					<_ContextMenu.Item
148						dir={dir}
149						draggable={false}
150						className="tlui-button tlui-button__menu"
151						data-testid={`${sourceId}.${id}`}
152						onPointerUp={(e) => {
153							// Prevent right-click pointerup from triggering item selection.
154							// Radix calls click() on pointerup when the pointer wasn't pressed
155							// on the item, but doesn't check the button — so a right-click
156							// release while moving across the menu selects the item under the cursor.
157							if (e.button !== 0) {
158								preventDefault(e)
159							}
160						}}
161						onSelect={(e) => {
162							if (noClose) preventDefault(e)
163							if (disableClicks) {
164								setDisableClicks(false)
165							} else {
166								onSelect(sourceId)
167							}
168						}}
169					>
170						<span className="tlui-button__label" draggable={false}>
171							{labelStr}
172						</span>
173						{iconLeft && <TldrawUiButtonIcon icon={iconLeft} small />}
174						{kbd && <TldrawUiKbd>{kbd}</TldrawUiKbd>}
175						{spinner && <Spinner />}
176					</_ContextMenu.Item>
177				)
178			}
179			case 'small-icons':
180			case 'icons': {
181				return (
182					<TldrawUiToolbarButton
183						data-testid={`${sourceId}.${id}`}
184						type="icon"
185						title={titleStr}
186						disabled={disabled}
187						onClick={() => onSelect(sourceId)}
188					>
189						<TldrawUiButtonIcon icon={icon!} small />
190					</TldrawUiToolbarButton>
191				)
192			}
193			case 'keyboard-shortcuts': {
194				if (!kbd) {
195					console.warn(
196						`Menu item '${label}' isn't shown in the keyboard shortcuts dialog because it doesn't have a keyboard shortcut.`
197					)
198					return null
199				}
200	
201				return (
202					<div className="tlui-shortcuts-dialog__key-pair" data-testid={`${sourceId}.${id}`}>
203						<div className="tlui-shortcuts-dialog__key-pair__key">{labelStr}</div>
204						<div className="tlui-shortcuts-dialog__key-pair__value">
205							<TldrawUiKbd visibleOnMobileLayout>{kbd}</TldrawUiKbd>
206						</div>
207					</div>
208				)
209			}
210			case 'helper-buttons': {
211				return (
212					<TldrawUiButton
213						type="low"
214						data-testid={`${sourceId}.${id}`}
215						onClick={() => onSelect(sourceId)}
216					>
217						<TldrawUiButtonIcon icon={icon!} />
218						<TldrawUiButtonLabel>{labelStr}</TldrawUiButtonLabel>
219					</TldrawUiButton>
220				)
221			}
222			case 'toolbar': {
223				if (onDragStart) {
224					return (
225						<DraggableToolbarButton
226							id={id}
227							icon={icon}
228							onSelect={onSelect}
229							onDragStart={onDragStart}
230							labelStr={labelStr}
231							titleStr={titleStr}
232							disabled={disabled}
233							isSelected={isSelected}
234						/>
235					)
236				}
237				return (
238					<TldrawUiToolbarButton
239						aria-label={labelStr}
240						aria-pressed={isSelected ? 'true' : 'false'}
241						data-testid={`tools.${id}`}
242						data-value={id}
243						disabled={disabled}
244						onClick={() => onSelect('toolbar')}
245						onTouchStart={(e) => {
246							preventDefault(e)
247							onSelect('toolbar')
248						}}
249						title={titleStr}
250						type="tool"
251					>
252						<TldrawUiButtonIcon icon={icon!} />
253					</TldrawUiToolbarButton>
254				)
255			}
256			case 'toolbar-overflow': {
257				if (onDragStart) {
258					return (
259						<DraggableToolbarButton
260							id={id}
261							icon={icon}
262							onSelect={onSelect}
263							onDragStart={onDragStart}
264							labelStr={labelStr}
265							titleStr={titleStr}
266							disabled={disabled}
267							isSelected={isSelected}
268							overflow
269						/>
270					)
271				}
272				return (
273					<TldrawUiToolbarButton
274						aria-label={labelStr}
275						aria-pressed={isSelected ? 'true' : 'false'}
276						isActive={isSelected}
277						data-testid={`tools.more.${id}`}
278						data-value={id}
279						disabled={disabled}
280						onClick={() => onSelect('toolbar')}
281						title={titleStr}
282						type="icon"
283					>
284						<TldrawUiButtonIcon icon={icon!} />
285					</TldrawUiToolbarButton>
286				)
287			}
288			default: {
289				throw exhaustiveSwitchError(menuType)
290			}
291		}
292	}
293	
294	function useDraggableEvents(
295		onDragStart: TLUiToolItem['onDragStart'],
296		onSelect: TLUiToolItem['onSelect']
297	) {
298		const editor = useEditor()
299		const events = useMemo(() => {
300			let state = { name: 'idle' } as
301				| {
302						name: 'idle'
303				  }
304				| {
305						name: 'pointing'
306						screenSpaceStart: VecModel
307				  }
308				| {
309						name: 'dragging'
310						screenSpaceStart: VecModel
311				  }
312				| {
313						name: 'dragged'
314				  }
315	
316			function handlePointerDown(e: React.PointerEvent<HTMLButtonElement>) {
317				state = {
318					name: 'pointing',
319					screenSpaceStart: { x: e.clientX, y: e.clientY },
320				}
321	
322				e.currentTarget.setPointerCapture(e.pointerId)
323			}
324	
325			function handlePointerMove(e: React.PointerEvent<HTMLButtonElement>) {
326				if ((e as any).isSpecialRedispatchedEvent) return
327	
328				if (state.name === 'pointing') {
329					const distanceSq = Vec.Dist2(state.screenSpaceStart, { x: e.clientX, y: e.clientY })
330					if (
331						distanceSq >
332						(editor.getInstanceState().isCoarsePointer
333							? editor.options.uiCoarseDragDistanceSquared
334							: editor.options.uiDragDistanceSquared)
335					) {
336						const screenSpaceStart = state.screenSpaceStart
337						state = {
338							name: 'dragging',
339							screenSpaceStart,
340						}
341	
342						editor.run(() => {
343							editor.setCurrentTool('select')
344	
345							// Set origin point
346							editor.dispatch({
347								type: 'pointer',
348								target: 'canvas',
349								name: 'pointer_down',
350								...getPointerInfo(editor, e),
351								point: screenSpaceStart,
352							})
353	
354							// Pointer down potentially selects shapes, so we need to deselect them.
355							editor.selectNone()
356	
357							// start drag
358							onDragStart?.('toolbar', {
359								type: 'pointer',
360								target: 'canvas',
361								name: 'pointer_move',
362								...getPointerInfo(editor, e),
363								point: screenSpaceStart,
364							})
365	
366							hideAllTooltips()
367							editor.getContainer().focus()
368						})
369					}
370				}
371			}
372	
373			function handlePointerUp(e: React.PointerEvent<HTMLButtonElement>) {
374				if ((e as any).isSpecialRedispatchedEvent) return
375	
376				e.currentTarget.releasePointerCapture(e.pointerId)
377	
378				editor.dispatch({
379					type: 'pointer',
380					target: 'canvas',
381					name: 'pointer_up',
382					...getPointerInfo(editor, e),
383				})
384			}
385	
386			function handleClick() {
387				if (state.name === 'dragging' || state.name === 'dragged') {
388					state = { name: 'idle' }
389					return true
390				}
391	
392				state = { name: 'idle' }
393				onSelect?.('toolbar')
394				return false
395			}
396	
397			return {
398				onPointerDown: handlePointerDown,
399				onPointerMove: handlePointerMove,
400				onPointerUp: handlePointerUp,
401				onClick: handleClick,
402			}
403		}, [onDragStart, editor, onSelect])
404	
405		return events
406	}
407	
408	function DraggableToolbarButton({
409		id,
410		labelStr,
411		titleStr,
412		disabled,
413		isSelected,
414		icon,
415		onSelect,
416		onDragStart,
417		overflow,
418	}: {
419		id: string
420		disabled: boolean
421		labelStr?: string
422		titleStr?: string
423		isSelected?: boolean
424		icon: TLUiMenuItemProps['icon']
425		onSelect: TLUiMenuItemProps['onSelect']
426		onDragStart: TLUiMenuItemProps['onDragStart']
427		overflow?: boolean
428	}) {
429		const events = useDraggableEvents(onDragStart, onSelect)
430	
431		if (overflow) {
432			return (
433				<TldrawUiToolbarButton
434					aria-label={labelStr}
435					aria-pressed={isSelected ? 'true' : 'false'}
436					isActive={isSelected}
437					className="tlui-button-grid__button"
438					data-testid={`tools.more.${id}`}
439					data-value={id}
440					disabled={disabled}
441					title={titleStr}
442					type="icon"
443					{...events}
444				>
445					<TldrawUiButtonIcon icon={icon!} />
446				</TldrawUiToolbarButton>
447			)
448		}
449	
450		return (
451			<TldrawUiToolbarButton
452				aria-label={labelStr}
453				aria-pressed={isSelected ? 'true' : 'false'}
454				data-testid={`tools.${id}`}
455				data-value={id}
456				disabled={disabled}
457				onTouchStart={(e) => {
458					preventDefault(e)
459					onSelect('toolbar')
460				}}
461				title={titleStr}
462				type="tool"
463				{...events}
464			>
465				<TldrawUiButtonIcon icon={icon!} />
466			</TldrawUiToolbarButton>
467		)
468	}
