describe('removing whole action groups hides their submenu', () => {
	async function openContextMenuOnSelectedShape(overrides?: TLUiOverrides) {
		const id = createShapeId()
		await renderTldrawComponent(
			<Tldraw
				overrides={overrides}
				onMount={(editor) => {
					editor.createShape({ id, type: 'geo' })
					editor.select(id)
				}}
			/>,
			{ waitForPatterns: false }
		)
		const canvas = await screen.findByTestId('canvas')
		fireEvent.contextMenu(canvas)
		await screen.findByTestId('context-menu')
	}

	it('shows the copy-as and export-as submenus by default', async () => {
		await openContextMenuOnSelectedShape()
		expect(screen.queryByTestId('context-menu-sub.copy-as-button')).not.toBeNull()
		expect(screen.queryByTestId('context-menu-sub.export-as-button')).not.toBeNull()
	})

	// Regression: removing an entire group of related actions used to leave the
	// submenu trigger behind, because a non-action item (the transparent-background
	// toggle) kept the submenu from being empty.
	it('hides the copy-as submenu when all copy-as actions are removed', async () => {
		const overrides: TLUiOverrides = {
			actions(_editor, actions) {
				delete actions['copy-as-svg']
				delete actions['copy-as-png']
				delete actions['copy-as-json']
				return actions
			},
		}
		await openContextMenuOnSelectedShape(overrides)
		expect(screen.queryByTestId('context-menu-sub.copy-as-button')).toBeNull()
		// the sibling export-as submenu is unaffected
		expect(screen.queryByTestId('context-menu-sub.export-as-button')).not.toBeNull()
	})

	it('hides the export-as submenu when all export-as actions are removed', async () => {
		const overrides: TLUiOverrides = {
			actions(_editor, actions) {
				delete actions['export-as-svg']
				delete actions['export-as-png']
				return actions
			},
		}
		await openContextMenuOnSelectedShape(overrides)
		expect(screen.queryByTestId('context-menu-sub.export-as-button')).toBeNull()
		// the sibling copy-as submenu is unaffected
		expect(screen.queryByTestId('context-menu-sub.copy-as-button')).not.toBeNull()
	})
})

